#include <stdio.h>
#include <math.h>

double sq(double x) { return x * x; }

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    double vecs[M][N];
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            scanf("%lf", &vecs[i][j]);
        }
    }

    double total = 0.0;
    // first vector stored as is
    for (int j = 0; j < N; j++) {
        total += sq(vecs[0][j]);
    }

    for (int i = 1; i < M; i++) {
        double best = 0.0;
        for (int j = 0; j < N; j++) {
            best += sq(vecs[i][j]);
        }

        // try all previous vectors
        for (int k = 0; k < i; k++) {
            double dot = 0.0, norm2 = 0.0;
            for (int j = 0; j < N; j++) {
                dot += vecs[i][j] * vecs[k][j];
                norm2 += sq(vecs[k][j]);
            }
            double c = dot / norm2;
            double residual = 0.0;
            for (int j = 0; j < N; j++) {
                residual += sq(vecs[i][j] - c * vecs[k][j]);
            }
            if (residual < best) best = residual;
        }
        total += best;
    }

    printf("%.6lf\n", total);
    return 0;
}

