}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int main(void) {
    int N, D;
    if (scanf("%d %d", &N, &D) != 2) return 0;

    double *a = (double *)malloc((size_t)N * D * sizeof(double));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < D; ++j) {
            scanf("%lf", &a[i * D + j]);
        }
    }

    /* Build complete graph where edge weight between i and j is
       ||vi||^2 - ( (vi·vj)^2 / ||vj||^2 ) if j is parent of i.
       For minimizing total after optimal ordering/recording, this
       reduces to MST on undirected graph with weight
       min( residual i from j, residual j from i ).
       Add super-root 0 with edge weight ||vi||^2. Then MST. */

    double *norm2 = (double *)malloc((size_t)N * sizeof(double));
    for (int i = 0; i < N; ++i) {
        double s = 0.0;
        for (int k = 0; k < D; ++k) {
            double x = a[i * D + k];
            s += x * x;
        }
        norm2[i] = s;
    }

    int M = N + 1; /* include super-root 0, vectors are 1..N */

    double *minCost = (double *)malloc((size_t)M * sizeof(double));
    char *used = (char *)calloc((size_t)M, sizeof(char));

    minCost[0] = 0.0;
    for (int i = 1; i <= N; ++i) minCost[i] = norm2[i - 1];

    double ans = 0.0;

    for (int it = 0; it < M; ++it) {
        int v = -1;
        for (int i = 0; i < M; ++i) {
            if (!used[i] && (v == -1 || minCost[i] < minCost[v])) v = i;
        }
        used[v] = 1;
        ans += minCost[v];

        if (v == 0) continue;

        int vi = v - 1;
        for (int u = 1; u <= N; ++u) {
            if (used[u]) continue;
            int ui = u - 1;

            double dot = 0.0;
            for (int k = 0; k < D; ++k) {
                dot += a[vi * D + k] * a[ui * D + k];
            }

            double w1 = norm2[vi];
            if (norm2[ui] > 0.0) {
                double t = dot * dot / norm2[ui];
                w1 = norm2[vi] - t;
            }

            double w2 = norm2[ui];
            if (norm2[vi] > 0.0) {
                double t = dot * dot / norm2[vi];
                w2 = norm2[ui] - t;
            }

            double w = (w1 < w2 ? w1 : w2);
            if (w < minCost[u]) minCost[u] = w;
        }
    }

    printf("%.10f\n", ans);

    free(a);
    free(norm2);
    free(minCost);
    free(used);
    return 0;
}

