    for (int i = 0; i < n; i++) {
        for (int d = 0; d < dim; d++) {
            cin >> vec[i][d];
        }
    }

    vector<double> norm2(n);
    for (int i = 0; i < n; i++) {
        double s = 0;
        for (int d = 0; d < dim; d++) s += sq(vec[i][d]);
        norm2[i] = s;
    }

    vector<bool> used(n, false);
    vector<double> min_cost(n, 1e100);
    min_cost[0] = 0;
    double total = 0;

    for (int iter = 0; iter < n; iter++) {
        int u = -1;
        double best = 1e100;
        for (int i = 0; i < n; i++) {
            if (!used[i] && min_cost[i] < best) {
                best = min_cost[i];
                u = i;
            }
        }
        used[u] = true;
        total += best;

        for (int v = 0; v < n; v++) {
            if (!used[v]) {
                double dot = 0;
                for (int d = 0; d < dim; d++) dot += vec[u][d] * vec[v][d];
                double cost;
                if (norm2[u] == 0) {
                    cost = norm2[v];
                } else {
                    cost = norm2[v] - dot * dot / norm2[u];
                }
                if (cost < min_cost[v]) min_cost[v] = cost;
            }
        }
    }

    cout << fixed << setprecision(6) << total << "\n";
    return 0;
}

