#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, D;
    cin >> N >> D;

    vector<vector<double>> a(N, vector<double>(D));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < D; ++j) cin >> a[i][j];
    }

    // Weight of recording vector i directly
    vector<double> self(N, 0.0);
    for (int i = 0; i < N; ++i) {
        for (int k = 0; k < D; ++k) self[i] += a[i][k] * a[i][k];
    }

    // Weight of recording i as (a_i - c * a_j) for optimal real c
    // min_c ||a_i - c a_j||^2 = ||a_i||^2 - (dot(i,j)^2 / ||a_j||^2), if ||a_j||^2 > 0
    // If a_j is zero, best is c arbitrary and cost = ||a_i||^2.
    struct Edge {
        int u, v;
        double w;
    };
    vector<Edge> edges;
    edges.reserve((long long)N * (N - 1) / 2 + N);

    // Super source = N, edge to each i with cost self[i]
    for (int i = 0; i < N; ++i) {
        edges.push_back({N, i, self[i]});
    }

    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            double dotij = 0.0;
            for (int k = 0; k < D; ++k) dotij += a[i][k] * a[j][k];

            double cij = self[i];
            if (self[j] > 0) cij = self[i] - dotij * dotij / self[j];

            double cji = self[j];
            if (self[i] > 0) cji = self[j] - dotij * dotij / self[i];

            // Since in undirected MST we can connect i and j and choose orientation later,
            // use the better of the two possible directed costs.
            double w = min(cij, cji);
            if (w < 0 && w > -1e-12) w = 0; // numerical cleanup
            edges.push_back({i, j, w});
        }
    }

    // Kruskal on N+1 nodes (0..N-1 vectors, N = super source)
    sort(edges.begin(), edges.end(), [](const Edge& a, const Edge& b) {
        return a.w < b.w;
    });

    vector<int> parent(N + 1), rnk(N + 1, 0);
    iota(parent.begin(), parent.end(), 0);

    function<int(int)> find = [&](int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    };

    auto unite = [&](int x, int y) -> bool {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        if (rnk[x] < rnk[y]) swap(x, y);
        parent[y] = x;
        if (rnk[x] == rnk[y]) ++rnk[x];
        return true;
    };

    double ans = 0.0;
    int need = N; // MST on N+1 nodes uses N edges
    for (const auto& e : edges) {
        if (unite(e.u, e.v)) {
            ans += e.w;
            if (--need == 0) break;
        }
    }

    cout.setf(ios::fixed);
    cout << setprecision(10) << ans << '\n';
    return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int d = sc.nextInt();
        double[][] vectors = new double[n][d];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < d; j++) {
                vectors[i][j] = sc.nextDouble();
            }
        }

        double[][] basis = new double[n][d];
        int rank = 0;
        double sumSq = 0.0;

        for (int i = 0; i < n; i++) {
            double[] vec = vectors[i].clone();
            for (int j = 0; j < rank; j++) {
                double dot = 0.0, normSq = 0.0;
                for (int k = 0; k < d; k++) {
                    dot += vec[k] * basis[j][k];
                    normSq += basis[j][k] * basis[j][k];
                }
                double coeff = dot / normSq;
                for (int k = 0; k < d; k++) {
                    vec[k] -= coeff * basis[j][k];
                }
            }
            double normSq = 0.0;
            for (int k = 0; k < d; k++) {
                normSq += vec[k] * vec[k];
            }
            if (normSq > 1e-12) {
                basis[rank] = vec;
                rank++;
                sumSq += normSq;
            }
        }

        System.out.printf("%.10f%n", sumSq);
    }
}

