public class Main {
    static int[] parent;
    static int find(int x) { return parent[x] == x ? x : (parent[x] = find(parent[x])); }
    static boolean union(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        parent[a] = b; return true;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), d = sc.nextInt();
        double[][] v = new double[n][d];
        for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) v[i][j] = sc.nextDouble();
        double[] sq = new double[n];
        for (int i = 0; i < n; i++) for (int j = 0; j < d; j++) sq[i] += v[i][j]*v[i][j];
        double totalSq = 0; for (double s : sq) totalSq += s;
        List<double[]> edges = new ArrayList<>();
        for (int i = 0; i < n; i++) for (int j = i+1; j < n; j++) {
            double dot = 0; for (int k = 0; k < d; k++) dot += v[i][k]*v[j][k];
            double w1 = sq[i] > 1e-12 ? dot*dot/sq[i] : 0;
            double w2 = sq[j] > 1e-12 ? dot*dot/sq[j] : 0;
            edges.add(new double[]{Math.max(w1,w2), i, j, w1 >= w2 ? i : j});
        }
        edges.sort((a,b) -> Double.compare(b[0],a[0]));
        parent = new int[n]; for (int i = 0; i < n; i++) parent[i] = i;
        double savings = 0;
        for (double[] e : edges) { int a=(int)e[1],b=(int)e[2]; if(union(a,b)) savings += e[0]; }
        System.out.printf("%.6f%n", totalSq - savings);
    }
}

import java.io.*;
import java.util.*;

/*
We have n vectors in d-dimensional Euclidean space.
For each vector i, when recording it we may either:
 - record it directly, contributing ||vi||^2
 - or record it as vi - c * vj for some previously recorded j and real c.
   For fixed i,j the best c is projection coefficient, and the remaining squared norm is
   ||vi||^2 - (vi·vj)^2 / ||vj||^2   (if vj != 0)

Thus if we choose a parent j for i, the cost contributed by i depends only on i and j.
Since each vector can only refer to a previously recorded vector, any feasible recording order
corresponds to a rooted directed forest where each node either has no parent (record directly)
or has one parent. Any forest can be ordered parent-before-child, so the problem becomes:

Choose for each i either no parent with cost rootCost[i] = ||vi||^2,
or a parent j != i with cost edgeCost[j][i] = ||vi||^2 - (vi·vj)^2 / ||vj||^2,
minimizing total cost, under the condition that chosen parent pointers form a directed forest.

This is exactly the minimum spanning arborescence / directed MST with a super-root s:
add edge s -> i of cost rootCost[i], and every j -> i of cost edgeCost[j][i].
Find minimum-cost arborescence rooted at s. Since all nodes are reachable from s directly,
Edmonds' algorithm applies.

Input format is not explicitly given in the statement excerpt, so we use the natural one:
n d
then n lines each containing d real numbers.

Output the minimum sum with sufficient precision.
*/

public class Main {
    static class Edge {
        int from, to;
        double w;
        Edge(int f, int t, double w) {
            this.from = f;
            this.to = t;
            this.w = w;
        }
    }

    static final double INF = 1e100;
    static final double EPS = 1e-12;

    // Directed MST / minimum arborescence rooted at root over nodes [0..N-1]
    static double dmst(int N, int root, List<Edge> edges) {
        double res = 0.0;

        while (true) {
            double[] in = new double[N];
            int[] pre = new int[N];
            Arrays.fill(in, INF);
            Arrays.fill(pre, -1);

            for (Edge e : edges) {
                if (e.from != e.to && e.w + EPS < in[e.to]) {
                    in[e.to] = e.w;
                    pre[e.to] = e.from;
                }
            }

            in[root] = 0.0;

            for (int i = 0; i < N; i++) {
                if (in[i] >= INF / 2) return Double.POSITIVE_INFINITY; // unreachable
            }

            int cnt = 0;
            int[] id = new int[N];
            int[] vis = new int[N];
            Arrays.fill(id, -1);
            Arrays.fill(vis, -1);

            for (int i = 0; i < N; i++) res += in[i];

            for (int i = 0; i < N; i++) {
                int v = i;
                while (vis[v] != i && id[v] == -1 && v != root) {
                    vis[v] = i;
                    v = pre[v];
                }
                if (v != root && id[v] == -1) {
                    for (int u = pre[v]; u != v; u = pre[u]) id[u] = cnt;
                    id[v] = cnt++;
                }
            }

            if (cnt == 0) break; // no cycle

            for (int i = 0; i < N; i++) {
                if (id[i] == -1) id[i] = cnt++;
            }

            List<Edge> newEdges = new ArrayList<>();
            for (Edge e : edges) {
                int u = id[e.from];
                int v = id[e.to];
                if (u != v) {
                    newEdges.add(new Edge(u, v, e.w - in[e.to]));
                }
            }

            root = id[root];
            N = cnt;
            edges = newEdges;
        }

        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n;
        int d;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        d = fs.nextInt();

        double[][] a = new double[n][d];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < d; j++) a[i][j] = fs.nextDouble();
        }

        double[] norm = new double[n];
        for (int i = 0; i < n; i++) {
            double s = 0;
            for (int j = 0; j < d; j++) s += a[i][j] * a[i][j];
            norm[i] = s;
        }

        int root = n;
        List<Edge> edges = new ArrayList<>();

        // super-root edges: record directly
        for (int i = 0; i < n; i++) {
            edges.add(new Edge(root, i, norm[i]));
        }

        // use another vector as reference
        for (int j = 0; j < n; j++) {
            if (norm[j] <= EPS) continue; // zero vector cannot help as divisor
            for (int i = 0; i < n; i++) {
                if (i == j) continue;
                double dot = 0;
                for (int k = 0; k < d; k++) dot += a[i][k] * a[j][k];
                double cost = norm[i] - dot * dot / norm[j];
                if (cost < 0 && cost > -1e-9) cost = 0; // numerical cleanup
                edges.add(new Edge(j, i, cost));
            }
        }

        double ans = dmst(n + 1, root, edges);
        System.out.printf(Locale.US, "%.10f%n", ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}
